with scored as (select id, customer_id, account_type, balance, opened_date, status, lead(balance, 1) over (order by balance, id) as next_balance, sum(balance) over (order by balance, id rows between unbounded preceding and current row) as cumulative_balance, rank() over (partition by account_type order by balance desc nulls first) as balance_rank, lead(balance, 1) over (partition by account_type order by balance, id) as next_balance_2, last_value(balance) ignore nulls over (partition by account_type order by balance, id rows between unbounded preceding and current row) as last_known_balance from accounts), metrics as (select id, customer_id, account_type, balance, opened_date, status, next_balance, cumulative_balance, balance_rank, next_balance_2, last_known_balance, last_value(next_balance_2, true) over (partition by status order by next_balance_2, id rows between unbounded preceding and current row) as last_known_next_balance_2, sum(next_balance_2) over (order by next_balance, id rows between unbounded preceding and current row) as running_next_balance_2, lead(next_balance, 1) over (partition by account_type order by cumulative_balance, id) as next_next_balance from scored), matched_keys as (select account_type from metrics intersect select account_type from accounts where account_type <> 'LOAN'), kept_rows as (select s.* from metrics s inner join matched_keys k on s.account_type = k.account_type), with_windows as (select *, dense_rank() over (order by running_next_balance_2) as running_next_balance_2_dense_rank, dense_rank() over (partition by customer_id order by last_known_next_balance_2 desc nulls first) as last_known_next_balance_2_dense_rank, percent_rank() over (order by balance desc) as balance_percent_rank, avg(next_balance) over (partition by account_type) as account_type_avg_next_balance, avg(balance_rank) over (partition by status, account_type) as status_avg_balance_rank from kept_rows), filtered as (select *, next_next_balance * last_known_next_balance_2_dense_rank as next_next_balance_times_last_known_next_balance_2_dense_rank from with_windows where status is not null), daily as (select account_type, count(*) as cnt, count(distinct status) as distinct_status, sum(case when status = 'FROZEN' then last_known_balance else 0 end) as frozen_last_known_balance from filtered group by account_type having distinct_status >= 1) select account_type, cnt, distinct_status, case when account_type rlike '^(LOAN|SAVINGS)$' then 'PRIORITY' when account_type rlike '^(CHECKING|CREDIT)$' then 'CORE' else 'GROUP_A' end as account_type_zone from daily order by distinct_status;
